# Standard library
import uuid

# Third-party
from sqlalchemy import func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, ReferenceWithFactorMixin


class CoreRefPointReason(Base, ReferenceWithFactorMixin):
    __tablename__ = "core_ref_point_reason"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        description=(
            "Primary key UUID, auto-generated by the database. Uniquely "
            "identifies a reason for awarding gamification points such as "
            "Track Completed, Achievement Unlocked, or POI Visited."
        ),
    )
